// DebugBuddy API — read what the backend sent.
// n8n holds NO state. The backend owns sessions and sends the whole story.
const b = $json.body || {};

const fullText = (b.full_report_text || '').trim();
if (!fullText) {
  throw new Error('full_report_text is required');
}

return [{ json: {
  session_id: b.session_id || null,
  full_report_text: fullText,
  iteration: Number(b.iteration) || 1,
  max_iterations: Number(b.max_iterations) || 3
} }];

// DebugBuddy API — Context Builder
const intake = $json.output || {};
const src = $('Parse Input').first().json;
return [{ json: { ...src, intake: {
  summary: intake.summary,
  category: intake.category,
  severity: intake.severity,
  known_information: intake.known_information || {},
  requires_clarification: intake.requires_clarification
} } }];

