// DebugBuddy API — report response
const ev = $('Readiness Evaluator').first().json;
const agent = $('Engineering Report Agent').first().json.output || {};
let message = $json.text;
if (ev.forced) {
  message += '\n\n---\n_Produced after ' + ev.iteration +
    ' rounds without reaching the readiness threshold (score ' +
    ev.readiness_score + '/100). Remaining gaps are listed above._';
}
return [{ json: {
  status: 'report_ready',
  session_id: ev.session_id,
  iteration: ev.iteration,
  readiness_score: ev.readiness_score,
  confidence: ev.confidence,
  forced: ev.forced,
  intake: ev.intake,
  report: agent,
  message
} }];

