const ev = $('Readiness Evaluator').first().json;
const agent = $('Clarification Agent').first().json.output || {};
return [{ json: {
  status: 'needs_clarification',
  session_id: ev.session_id,
  iteration: ev.iteration,
  readiness_score: ev.readiness_score,
  confidence: ev.confidence,
  forced: false,
  intake: ev.intake,
  missing_information: ev.missing_information,
  questions: agent.questions || [],
  message: $json.text
} }];
